import { SETTINGS } from "../../utils/constants";
import { cloneTemplate } from "../../utils/utils";
export class ProductCardView {
    render(product) {
        const cardTemplate = document.querySelector(SETTINGS.cardTemplate);
        if (!cardTemplate) {
            throw new Error(`Template with ID "${SETTINGS.cardTemplate}" not found.`);
        }
        const card = cloneTemplate(cardTemplate);
        const titleElement = card.querySelector(SETTINGS.productSettings.title);
        const categoryElement = card.querySelector(SETTINGS.productSettings.category);
        const imageElement = card.querySelector(SETTINGS.productSettings.image);
        const priceElement = card.querySelector(SETTINGS.productSettings.price);
        if (titleElement)
            titleElement.textContent = product.name;
        if (categoryElement)
            categoryElement.textContent = product.category;
        if (imageElement)
            imageElement.src = product.image;
        if (priceElement)
            priceElement.textContent = `${product.price} синапсов`;
        return card;
    }
}
