import { ensureElement, cloneTemplate } from "../../utils/utils";
import { SETTINGS } from "../../utils/constants";
export class SuccessView {
    constructor() {
        // Инициализация элементов, которые будут использоваться в render
        this.content = document.createElement('div');
        this.closeButton = document.createElement('button');
    }
    render(totalPrice) {
        const template = document.querySelector(SETTINGS.successTemplate);
        if (!template) {
            throw new Error('Шаблон успешного заказа не найден');
        }
        const successElement = cloneTemplate(template);
        this.content = successElement;
        const priceElement = ensureElement(SETTINGS.success.description, this.content);
        priceElement.textContent = `Списано ${totalPrice} синапсов`;
        this.closeButton = ensureElement(SETTINGS.success.closeButton, this.content);
        // Возвращаем готовый элемент, управление модальным окном будет в контроллере
        return this.content;
    }
    getCloseButton() {
        return this.closeButton;
    }
}
