export class ProductController {
    constructor(api, events, pageView) {
        this.api = api;
        this.events = events;
        this.pageView = pageView;
        this.events.on('product:add', this.handleProductAdd.bind(this));
        this.events.on('product:open', this.handleProductOpen.bind(this));
    }
    async loadProducts() {
        try {
            const products = await this.api.getProductList();
            this.displayProducts(products);
        }
        catch (error) {
            console.error("Ошибка при загрузке товаров:", error);
        }
    }
    displayProducts(products) {
        const cards = products.map(product => {
            const cardView = new ProductCardView();
            const card = cardView.render(product);
            card.addEventListener('click', () => {
                this.events.emit('product:open', product);
            });
            return card;
        });
        this.pageView.updateGallery(cards);
    }
    handleProductAdd(product) {
        // Логика добавления товара в корзину
        console.log(`Товар добавлен в корзину: ${product.name}`);
    }
    handleProductOpen(product) {
        // Логика открытия модального окна с товаром
        console.log(`Открываем модальное окно для товара: ${product.name}`);
    }
}
