import { ModalController } from './components/controllers/modalController';
import { ProductController } from './components/controllers/ProductController';
import { BasketController } from './components/controllers/BasketController';
import { OrderController } from './components/controllers/OrderController';
import { PageView } from './components/view/PageView';
// 1. Создаем экземпляры классов
const events = new EventEmitter();
const api = new ProductAPI(CDN_URL, API_URL);
const pageElement = ensureElement(SETTINGS.page);
const page = new Page(pageElement, events);
const pageView = new PageView(events);
const modalElement = ensureElement(SETTINGS.modalTemplate);
const modal = new Modal(modalElement, events);
const modalController = new ModalController(modal, events);
const basket = new Basket();
const basketView = new BasketView(ensureElement(SETTINGS.basketTemplate), events);
const order = new Order();
const orderView = new OrderView(ensureElement(SETTINGS.orderTemplate), events);
const contactsView = new ContactsView(ensureElement(SETTINGS.contactsTemplate), events);
// 2. Создаем контроллеры
const productController = new ProductController(api, events, pageView);
const basketController = new BasketController(basket, basketView, events, modalController);
const orderController = new OrderController(order, orderView, contactsView, events, api, modalController, basket);
// 3. Инициализация приложения
productController.loadProducts();
// Пример: Обновление счетчика в хедере при загрузке страницы (если есть товары в корзине)
events.on('basket:count', (data) => {
    pageView.setBasketCounter(data.count);
});
events.on('product:open', (product) => {
    if (isIProduct(product)) { // Добавляем проверку типа
        const productModalView = new ProductModalView(events);
        modal.content = productModalView.render(product);
        modal.open();
    }
    else {
        console.error("Invalid product data received:", product);
        // Обрабатываем ситуацию, когда данные не соответствуют типу IProduct
        // Например, можно показать сообщение об ошибке пользователю или просто проигнорировать событие
    }
});
events.on('order:open', () => {
    modal.open();
});
window.addEventListener('load', () => {
    productController.loadProducts();
    basketController.updateBasketCounter();
});
// Чтобы приложение заработало, нужно в index.html прописать все классы и id которые указаны в файле constants.ts
console.log('Приложение запущено!');
