import { ensureElement, cloneTemplate } from "../../utils/utils";
import { SETTINGS } from "../../utils/constants";
export class OrderView {
    constructor(container, eventEmitter) {
        this.container = container;
        this.eventEmitter = eventEmitter;
    }
    render(order) {
        const template = document.querySelector(SETTINGS.orderTemplate);
        if (!template) {
            throw new Error('Шаблон не найден');
        }
        const orderElement = cloneTemplate(template);
        // Инициализация элементов формы
        this.form = ensureElement(SETTINGS.order.form, orderElement);
        this.paymentButtons = ensureElement(SETTINGS.order.paymentButtons, this.form);
        this.addressInput = ensureElement(SETTINGS.order.addressInput, this.form);
        this.submitButton = ensureElement(SETTINGS.order.submitButton, this.form);
        this.errors = ensureElement(SETTINGS.order.errors, this.form);
        // Обработчики событий
        this.paymentButtons.addEventListener('click', (event) => {
            const target = event.target;
            if (target.name === 'card' || target.name === 'cash') {
                this.eventEmitter.emit('payment:change', { method: target.name });
                this.eventEmitter.emit('order:validate');
            }
        });
        this.addressInput.addEventListener('input', () => {
            this.eventEmitter.emit('address:change', { value: this.addressInput.value });
            this.eventEmitter.emit('order:validate');
        });
        this.form.addEventListener('submit', (event) => {
            event.preventDefault();
            this.eventEmitter.emit('order:submit');
        });
        return orderElement;
    }
    // Методы для обновления состояния формы
    setPaymentMethod(method) {
        const onlineButton = ensureElement(SETTINGS.order.paymentButtonOnline, this.paymentButtons);
        const cashButton = ensureElement(SETTINGS.order.paymentButtonCash, this.paymentButtons);
        onlineButton.classList.toggle(SETTINGS.order.buttonActiveClass, method === 'card');
        cashButton.classList.toggle(SETTINGS.order.buttonActiveClass, method === 'cash');
    }
    setAddress(value) {
        this.addressInput.value = value;
    }
    setValidState(isValid, error) {
        this.submitButton.disabled = !isValid;
        this.errors.textContent = isValid ? '' : (error || 'Заполните все поля');
    }
}
