import { ensureElement } from "../../utils/utils";
import { SETTINGS } from "../../utils/constants";
export class ContactsView {
    constructor(container, eventEmitter) {
        this.eventEmitter = eventEmitter;
        this.container = container;
        this.form = ensureElement(SETTINGS.contacts.form, this.container);
        this.emailInput = ensureElement(SETTINGS.contacts.emailInput, this.form);
        this.submitButton = ensureElement(SETTINGS.contacts.submitButton, this.form);
        this.errors = ensureElement(SETTINGS.contacts.errors, this.form);
    }
    render() {
        this.emailInput.addEventListener('input', () => {
            this.eventEmitter.emit('contacts:validate');
        });
        this.phoneInput.addEventListener('input', () => {
            this.eventEmitter.emit('contacts:validate');
        });
        this.form.addEventListener('submit', (event) => {
            event.preventDefault();
            this.eventEmitter.emit('contacts:submit', {
                email: this.emailInput.value,
                phone: this.phoneInput.value,
            });
        });
        return this.container;
    }
}
